const express = require("express");
const db = require("../db");

const router = express.Router();

const idempotencyCache = new Map();

router.post("/", async (req, res) => {
  const key = req.get("Idempotency-Key");
  if (!key) return res.status(400).json({ error: "Idempotency-Key header required" });

  const cached = idempotencyCache.get(key);
  if (cached) return res.status(201).json(cached);

  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity) VALUES ($1, $2, $3) RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity]
  );

  idempotencyCache.set(key, row);
  setTimeout(() => idempotencyCache.delete(key), 24 * 60 * 60 * 1000);

  res.status(201).json(row);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) {
    return res.status(404).end();
  }
  res.json(row);
});

module.exports = router;

turns.text:
The connection drops during `await client.query(text, params)`. The promise rejects with a connection error. The catch block runs and tries `await client.query("ROLLBACK")` on a dead connection — that also fails. Now the ROLLBACK error overwrites the original error and gets rethrown, and the caller sees the wrong error message.

The finally block then releases the client (which may hang or fail silently if the connection is already gone). The request fails with the ROLLBACK error instead of the actual connection failure.

**The real issue:** ROLLBACK can fail and mask the original error. If the connection dies before BEGIN completes, you lose what went wrong. You should wrap the ROLLBACK in its own try-catch so the original error survives:

```javascript
catch (err) {
  try {
    await client.query("ROLLBACK");
  } catch {
    // ignore rollback failure
  }
  throw err;  // always rethrow original error
}
```

This way the caller gets the actual connection error, not a secondary rollback error. Postgres also auto-rolls back when a connection closes, so a failed ROLLBACK isn't catastrophic — you just need to not let it hide what happened.

