db.js.text:
const { Pool } = require("pg");

const pool = new Pool();

// Every read in the service goes through query(). Every write goes through
// write() — it exists so callers get the RETURNING row back in one shape and
// so there is exactly one place a transaction begins.
async function query(text, params) {
  const res = await pool.query(text, params);
  return res.rows;
}

async function write(text, params) {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const res = await client.query(text, params);
    await client.query("COMMIT");
    return res.rows[0];
  } catch (err) {
    try {
      await client.query("ROLLBACK");
    } catch (rollbackErr) {
      // Connection already down; rollback failed. Original error is what matters.
    }
    throw err;
  } finally {
    client.release();
  }
}

async function getOrCreateWithIdempotency(idempotencyKey, accountId, writeFn) {
  if (!idempotencyKey) return writeFn();

  const existing = await query(
    "SELECT response FROM idempotency_keys WHERE key = $1 AND account_id = $2",
    [idempotencyKey, accountId]
  );
  if (existing.length) return JSON.parse(existing[0].response);

  const result = await writeFn();
  await write(
    "INSERT INTO idempotency_keys (key, account_id, response) VALUES ($1, $2, $3) ON CONFLICT DO NOTHING",
    [idempotencyKey, accountId, JSON.stringify(result)]
  );
  return result;
}

module.exports = { query, write, getOrCreateWithIdempotency };

